const fs = require('fs')
const path = require('path')

const [nodeBinary, jsFile, json] = process.argv

if (!json || !json.endsWith('steam_api.json')) {
  throw new Error(`Please provide a path to steam_api.json as first argument`)
}

const data = require(path.resolve(json));
const steamHeadersDir = path.dirname(path.resolve(json));

const outFileCpp = 'src/steam-aux.cpp'
const incompleteStructs = new Set([
  'SteamDatagramHostedAddress',
  'SteamDatagramGameCoordinatorServerLogin',
])

const cpp = [
  '// this file is autogenerated by generate-aux.js - https://github.com/menduz/zig-steamworks',
  `#include <cstdio>`,
  `#include <concepts>`,
  `#include <type_traits>`,

  `#define private public`,
  `#import "steam_api.h"`,
  `#import "steam_gameserver.h"`,
  `#import "steamnetworkingfakeip.h"`,
  `#undef private`,
]

if (fs.existsSync(path.join(steamHeadersDir, 'steamdatagram_tickets.h'))) {
  cpp.push(`#import "steamdatagram_tickets.h"`)
}

var isFirst = true

function writeDumpStruct(struct) {
  const structName = struct.struct

  if (incompleteStructs.has(structName)) return

  { // struct
    const comma = isFirst ? '' : ',' 
    if(isFirst) isFirst = false;
    cpp.push(`  // ${structName}`)
    cpp.push(`  { std::fprintf(stdout, "${comma}\\"${structName}\\": {");`)

    { // fields
      cpp.push(`    { std::fprintf(stdout, "\\"fields\\": [");`);

      cpp.push(`      struct ${structName}    *p_${structName} = 0;`)

      struct.fields.forEach((f, i) => {
        const comma = i == struct.fields.length - 1 ? '' : ',\\n'
        const memberExpr = structName == 'SteamNetworkingConfigValue_t' && f.fieldname == 'm_int64'
          ? `m_val.m_int64`
          : f.fieldname

        cpp.push(`      std::fprintf(stdout, "  {\\"field\\": \\"${f.fieldname}\\", \\"size\\": %zu, \\"align\\": %zu}${comma}", sizeof(p_${structName}->${memberExpr}), alignof(p_${structName}->${memberExpr}));`);
      })

      cpp.push(`      std::fprintf(stdout, "],\\n");`)
      cpp.push(`    }`)
    }

    cpp.push(`    std::fprintf(stdout, "  \\"size\\": %zu, \\"align\\": %zu \\n", sizeof(${structName}), alignof(${structName}));`);

    cpp.push(`    std::fprintf(stdout, "}\\n");`)
    cpp.push(`  }`)
  }
}

{
  // cpp.push(`extern "C" int dump_all() {`)
  cpp.push(`int main() {`)
  cpp.push(`  std::fprintf(stdout, "{\\n");`);
  [...data.callback_structs, ...data.structs].forEach(writeDumpStruct);
  cpp.push(
    `  std::fprintf(stdout, "}\\n");`,
    `  return 0;`,
    `}`)
}

fs.writeFileSync(outFileCpp, cpp.join('\n'))
